import json, pandas as pd; trades = json.load(open('backend/data/trades_history.json')); df = pd.DataFrame(trades); df['is_win'] = df['result'].isin(['WIN', 'CLOSED_WIN']); df['is_loss'] = df['result'].isin(['LOSS', 'CLOSED_LOSS']); df = df[df['is_win'] | df['is_loss']]; print('\n--- Win Rate by Trade Source ---'); print(df.groupby('trade_source')['is_win'].agg(['count', 'mean']).rename(columns={'count': 'Total Trades', 'mean': 'Win Rate'}).apply(lambda x: round(x * 100, 1) if x.name == 'Win Rate' else x)); print('\n--- Win Rate by Conviction Grade ---'); print(df.groupby('conviction_grade')['is_win'].agg(['count', 'mean']).rename(columns={'count': 'Total Trades', 'mean': 'Win Rate'}).apply(lambda x: round(x * 100, 1) if x.name == 'Win Rate' else x))
